// Days a deal may sit in a stage before it counts as stale (docs/HUBSPOT_PLAN.md, build 5).
// Tests pin this node: limits of 0 and onlyDealIds keep test tasks on test deals.
return [{ json: { limits: { NEW: 1, CONTACTED: 3, CALL: 1, PROPOSAL: 7 }, onlyDealIds: [] } }];

// One item per open TCA deal (the search returns up to 100; plenty for this pipeline).
const cfg = $('Config').first().json;
const only = (cfg.onlyDealIds ?? []).map(String);
return ($('Find open deals').first().json.results ?? [])
  .filter((d) => !only.length || only.includes(String(d.id)))
  .map((d) => ({ json: { dealId: String(d.id), properties: d.properties } }));

const PORTAL = '247728856';
const PIPELINE = '2630364862';
const STAGE = { NEW: '4456833770', CONTACTED: '4456833771', CALL: '4456833772', PROPOSAL: '4456833773' };
const STAGE_NAME = { '4456833770': 'New lead', '4456833771': 'Contacted', '4456833772': 'Call booked', '4456833773': 'Proposal sent', '4456833775': 'Closed Won', '4456833776': 'Closed Lost' };
const DAY = 24 * 3600 * 1000;
const dealUrl = (id) => 'https://app-na2.hubspot.com/contacts/' + PORTAL + '/record/0-3/' + id;
const entered = (p) => Date.parse(p.hs_v2_date_entered_current_stage || p.createdate);

// Which deals are stale, whether each needs a new task, and who owns it.
const cfg = $('Config').first().json;
const limitFor = { [STAGE.NEW]: cfg.limits.NEW, [STAGE.CONTACTED]: cfg.limits.CONTACTED, [STAGE.CALL]: cfg.limits.CALL, [STAGE.PROPOSAL]: cfg.limits.PROPOSAL };
const owners = {};
for (const o of $('List owners').first().json.results ?? []) owners[String(o.id)] = { email: o.email, name: [o.firstName, o.lastName].filter(Boolean).join(' ') || o.email };
const deals = $('One item per deal').all();
const details = $('Deal tasks and meetings').all();
const tasks = $('Read tasks').all();
const meetings = $('Read meetings').all();
const ok = (r) => r.statusCode === 200 || r.statusCode === 207;
const now = Date.now();

const stale = [];
deals.forEach((d, i) => {
  const p = d.json.properties;
  const stage = p.dealstage;
  const limitDays = limitFor[stage];
  if (limitDays === undefined) return;
  let since = entered(p);
  let basis = 'in ' + STAGE_NAME[stage];
  if (stage === STAGE.CALL) {
    // A booked call only goes stale a day after it starts. No meeting: count from the stage change.
    const ms = (ok(meetings[i].json) ? meetings[i].json.body.results : [])
      .filter((m) => m.properties?.hs_meeting_outcome !== 'CANCELED' && m.properties?.hs_meeting_outcome !== 'RESCHEDULED')
      .map((m) => Date.parse(m.properties.hs_meeting_start_time))
      .filter((t) => !Number.isNaN(t));
    if (ms.length) { since = Math.max(...ms); basis = 'since the booked call'; }
  }
  const days = Math.floor((now - since) / DAY);
  if (Number.isNaN(days) || now - since < limitDays * DAY) return;
  const openTask = (ok(tasks[i].json) ? tasks[i].json.body.results : [])
    .some((t) => String(t.properties?.hs_task_subject ?? '').startsWith('[TCA sweep]') && t.properties?.hs_task_status !== 'COMPLETED');
  const ownerId = p.hubspot_owner_id ? String(p.hubspot_owner_id) : null;
  stale.push({
    dealId: d.json.dealId,
    dealName: p.dealname,
    stageName: STAGE_NAME[stage],
    days,
    limitDays,
    basis,
    ownerId,
    ownerEmail: ownerId ? owners[ownerId]?.email ?? null : null,
    ownerName: ownerId ? owners[ownerId]?.name ?? 'owner ' + ownerId : null,
    needsTask: !openTask,
  });
});
if (!stale.length) return [];
return [{ json: { stale } }];

// One HubSpot task per stale deal without an open sweeper task, due 17:00 Manila (09:00 UTC) on the day of the sweep.
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const due = Math.max(Date.parse(today + 'T09:00:00Z'), Date.now() + 3600 * 1000);
const out = [];
for (const s of $('Decide').first().json.stale.filter((x) => x.needsTask)) {
  const properties = {
    hs_task_subject: '[TCA sweep] Follow up: ' + s.dealName,
    hs_task_body: s.days + ' days ' + s.basis + ' (limit ' + s.limitDays + '). Created by the n8n stale-deal sweep; complete this task once the deal has moved on.',
    hs_timestamp: new Date(due).toISOString(),
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: 'MEDIUM',
    hs_task_type: 'TODO',
  };
  if (s.ownerId) properties.hubspot_owner_id = s.ownerId;
  out.push({ json: { body: { properties, associations: [{ to: { id: s.dealId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 216 }] }] } } });
}
return out;

// Owners to @-mention. Always at least one item, so the digest still runs when every deal is unclaimed.
const emails = [...new Set($('Decide').first().json.stale.map((s) => s.ownerEmail).filter(Boolean))];
return (emails.length ? emails : ['nobody@invalid.example']).map((email) => ({ json: { email } }));

const PORTAL = '247728856';
const PIPELINE = '2630364862';
const STAGE = { NEW: '4456833770', CONTACTED: '4456833771', CALL: '4456833772', PROPOSAL: '4456833773' };
const STAGE_NAME = { '4456833770': 'New lead', '4456833771': 'Contacted', '4456833772': 'Call booked', '4456833773': 'Proposal sent', '4456833775': 'Closed Won', '4456833776': 'Closed Lost' };
const DAY = 24 * 3600 * 1000;
const dealUrl = (id) => 'https://app-na2.hubspot.com/contacts/' + PORTAL + '/record/0-3/' + id;
const entered = (p) => Date.parse(p.hs_v2_date_entered_current_stage || p.createdate);

// One Slack digest for #leads. Deal names come from visitors: escape them.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const stale = $('Decide').first().json.stale;
const ids = {};
const owners = $('Owner items').all();
$input.all().forEach((r, i) => { if (r.json.ok && r.json.user?.id) ids[owners[i].json.email] = r.json.user.id; });
const lines = stale.map((s) => {
  const who = s.ownerEmail ? (ids[s.ownerEmail] ? '<@' + ids[s.ownerEmail] + '>' : esc(s.ownerName)) : '_unclaimed_';
  return '• <' + dealUrl(s.dealId) + '|' + esc(s.dealName) + '>: ' + s.days + ' days ' + esc(s.basis) + ' (limit ' + s.limitDays + ') · ' + who + (s.needsTask ? ' · task created' : ' · task already open');
});
const text = ':hourglass_flowing_sand: *Stale deals: ' + stale.length + '*\n' + lines.join('\n');
return [{ json: { channel: 'C0CAAG03B1A', text: 'Stale deals: ' + stale.length, blocks: [{ type: 'section', text: { type: 'mrkdwn', text: text.slice(0, 2900) } }], unfurl_links: false } }];

const r = $input.first().json;
if (r.ok === false) throw new Error('Slack API error: ' + r.error);
return $input.all();
